            aWandererI = aWandererI ^ ((((RotL64(aScatter, 47U) + RotL64(aOrbiterB, 39U)) + aOrbiterC) + aNonceWordC) + aWandererUpdateSaltF[(((31U - aIndex) + 4U)) & S_SALT1]);
