            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x9A5D973B56BD5770ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0xE167682E2F5E5330ULL) ^ aNonceWordD;
            aOrbiterA = RotL64((aOrbiterA * 0x04C258916066E335ULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0xE9C3644974F4C4CAULL;
