            aOrbiterD = RotL64((aOrbiterD * 0x6C9B80B430F16AD1ULL), 53U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterK) + 0xDD74919C0B1E5994ULL) + aOrbiterUpdateSaltF[(((31U - aIndex) + 26U)) & S_SALT1];
