            //
            aOrbiterD = ((aWandererJ + RotL64(aScatter, 6U)) + 0x225BAAF66A5C7729ULL) + aPhaseDOrbiterAssignSaltC[((aIndex + 22U)) & S_SALT1];
            aOrbiterF = ((aWandererK + RotL64(aPrevious, 23U)) + RotL64(aCarry, 19U)) + 0x027A69CD7C925D9FULL;
            aOrbiterE = ((aWandererC + RotL64(aIngress, 13U)) + RotL64(aCarry, 39U)) + 0x507A7088240F8812ULL;
            aOrbiterC = (aWandererA + RotL64(aCross, 57U)) + 0x7D903B361D8C50E2ULL;
