            aOrbiterI = (((aWandererI + RotL64(aScatter, 47U)) + RotL64(aCarry, 5U)) + 0x9993AD121A39409BULL) + aPhaseDOrbiterAssignSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterA = (aWandererD + RotL64(aCross, 41U)) + 0x447031E38BE50B8EULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterF) + 0x8B35EC6EB94B7426ULL) + aPhaseDOrbiterUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0xB4E6C6FEBDA43E9CULL;
            aOrbiterE = RotL64((aOrbiterE * 0x96C0F0F01DFDE3F1ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x98421B8A3032C895ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x8F43DE35C56FBF25ULL) ^ aPhaseDOrbiterUpdateSaltB[((aIndex + 7U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x5610C43138DB3433ULL), 43U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xB39266AEA5E8E90AULL;
