            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x6BCC5A93B711A788ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xBFB4E9E28CCD8137ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x06DA75443741FC81ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x9CA586A3A51E4050ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterE) ^ 0xE2B1CDB7DB87DCB3ULL) ^ aPhaseDOrbiterUpdateSaltE[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x29B7AF6F7B107EF3ULL), 23U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x76815260ECAB6034ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0xF47DE7E64C83DCE3ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x9907129A639416B1ULL), 37U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterH, 51U);
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterD, 57U));
