            //
            aWandererI = aWandererI + (((RotL64(aIngress, 35U) + aOrbiterC) + RotL64(aOrbiterA, 51U)) + aPhaseDWandererUpdateSaltE[(((31U - aIndex) + 24U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 51U) + RotL64(aOrbiterC, 3U)) + aOrbiterI);
