            aWandererD = aWandererD ^ (((RotL64(aCross, 57U) + RotL64(aOrbiterI, 11U)) + aOrbiterE) + aPhaseDWandererUpdateSaltC[((aIndex + 28U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aScatter, 12U) + RotL64(aOrbiterD, 30U)) + aOrbiterF);
            aWandererC = aWandererC ^ ((RotL64(aIngress, 5U) + RotL64(aOrbiterC, 19U)) + aOrbiterE);
