            aOrbiterJ = RotL64((aOrbiterJ * 0x6243120A5375406DULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xCD1A58EB15F0249CULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0x6087880FC2D99E5DULL) ^ aPhaseCOrbiterUpdateSaltF[(((31U - aIndex) + 18U)) & S_SALT1];
