            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0x28ED894965D5096CULL) ^ aPhaseCOrbiterUpdateSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xE4CB7DA9E59C5F35ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x526040990CD8CF67ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x7632F505C341A5BEULL;
            aOrbiterG = RotL64((aOrbiterG * 0x32FA41C4C2DF8A4FULL), 57U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x18D192FB51397CFCULL) + aPhaseCOrbiterUpdateSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0x2A529F7360ED3119ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE69FDF68ED2D220DULL), 3U);
            //
