            //
            aWandererI = aWandererI + (((RotL64(aPrevious, 37U) + aOrbiterF) + RotL64(aOrbiterK, 41U)) + aPhaseCWandererUpdateSaltC[((aIndex + 13U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 58U) + aOrbiterJ) + RotL64(aOrbiterB, 48U));
            aWandererH = aWandererH + ((((RotL64(aCross, 19U) + RotL64(aOrbiterG, 11U)) + aOrbiterK) + RotL64(aCarry, 53U)) + aPhaseCWandererUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aIngress, 51U) + aOrbiterH) + RotL64(aOrbiterD, 29U));
            aWandererK = aWandererK + ((RotL64(aCross, 5U) + aOrbiterD) + RotL64(aOrbiterK, 3U));
