            //
            aOrbiterK = ((aWandererF + RotL64(aIngress, 3U)) + 0x9337B67135696EFCULL) + aPhaseAOrbiterAssignSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterB = (aWandererH + RotL64(aScatter, 53U)) + 0x76F6AE8E8389BCDDULL;
            aOrbiterD = (aWandererD + RotL64(aCross, 35U)) + 0xA5A705A948AFA379ULL;
            aOrbiterG = (aWandererC + RotL64(aPrevious, 29U)) + 0xF26DA2BF0ABD5054ULL;
            aOrbiterC = (((aWandererG + RotL64(aScatter, 19U)) + RotL64(aCarry, 5U)) + 0x4ACA4D663DC104AAULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 16U)) & S_SALT1];
            aOrbiterE = ((aWandererI + RotL64(aPrevious, 10U)) + RotL64(aCarry, 41U)) + 0x2BBA02FBB57F135EULL;
