            //
            aScatter = (RotL64(aIngress, 23U) + RotL64(aCarry, 56U)) ^ (RotL64(aCross, 41U) ^ RotL64(aPrevious, 11U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = (aWandererI + RotL64(aScatter, 6U)) + 0x2BCDCE5FAE7DA267ULL;
            aOrbiterJ = ((aWandererH + RotL64(aPrevious, 21U)) + RotL64(aCarry, 35U)) + 0x3F1170947A62D42DULL;
            aOrbiterH = ((aWandererA + RotL64(aCross, 13U)) + RotL64(aCarry, 21U)) + 0xFC0FA3CE084C4438ULL;
            aOrbiterA = ((aWandererB + RotL64(aIngress, 37U)) + 0x6F55A2680DF42B40ULL) + aPhaseDOrbiterAssignSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterK = ((aWandererF + RotL64(aScatter, 43U)) + 0x4C06747ABE5CF176ULL) + aPhaseDOrbiterAssignSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterD = (aWandererC + RotL64(aCross, 29U)) + 0xA0CFBB3F7E91396FULL;
            aOrbiterG = ((aWandererE + RotL64(aIngress, 57U)) + RotL64(aCarry, 53U)) + 0x073F3FABEA5DA58BULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterJ) + 0x6289FB03BD0AD44EULL) + aPhaseDOrbiterUpdateSaltA[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xFA2748714B822EECULL;
