            aWandererG = aWandererG ^ ((RotL64(aScatter, 23U) + aOrbiterA) + RotL64(aOrbiterF, 10U));
            aWandererH = aWandererH + ((((RotL64(aPrevious, 47U) + RotL64(aOrbiterE, 37U)) + aOrbiterI) + RotL64(aCarry, 37U)) + aPhaseAWandererUpdateSaltE[((aIndex + 26U)) & S_SALT1]);
