            //
            aOrbiterE = (aWandererB + RotL64(aScatter, 13U)) + 0xE9351BEBE37AF1A0ULL;
            aOrbiterA = (((aWandererH + RotL64(aIngress, 35U)) + RotL64(aCarry, 51U)) + 0x6D6154E54527AD73ULL) + aPhaseCOrbiterAssignSaltC[((aIndex + 13U)) & S_SALT1];
            aOrbiterJ = (aWandererC + RotL64(aPrevious, 21U)) + 0x71489F408C9A233BULL;
            aOrbiterC = (aWandererK + RotL64(aCross, 53U)) + 0xE2974FC34DB242DCULL;
            aOrbiterK = ((aWandererI + RotL64(aScatter, 60U)) + 0x3A17C71491F392E4ULL) + aPhaseCOrbiterAssignSaltE[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aCross, 3U)) + RotL64(aCarry, 37U)) + 0xAE4F0674ABE76969ULL;
            aOrbiterF = ((aWandererE + RotL64(aPrevious, 27U)) + RotL64(aCarry, 5U)) + 0x8CA2BE49771454D3ULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0xE2ACFC0C1C7C5EB7ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x7177EE8F2CF31038ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x326624367A405E2FULL), 35U);
