            aOrbiterB = RotL64((aOrbiterB * 0x678D372C75D93653ULL), 13U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0x8CBF24C871591CD0ULL) + aPhaseCOrbiterUpdateSaltA[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x6AC32FAA99467D01ULL;
