            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xAEC6B197F6B86ED4ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterA) ^ 0x1F981791541ED899ULL) ^ aPhaseCOrbiterUpdateSaltD[((aIndex + 15U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x0188EDC6B5A0C939ULL), 5U);
