            aIngress ^= (RotL64(aFireLaneC[((aIndex + 24387U)) & S_BLOCK1], 3U) ^ RotL64(aPoisonLaneC[((aIndex + 20955U)) & S_BLOCK1], 51U));
            aIngress = TwistMix64::DiffuseC(aIngress);
