            aCross = (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 24201U)) & S_BLOCK1], 35U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 17825U)) & S_BLOCK1], 13U));
            aCross ^= (RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 18256U)) & S_BLOCK1], 56U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 20789U)) & S_BLOCK1], 21U));
