            //
            aOrbiterJ = ((aWandererA + RotL64(aCross, 53U)) + 0x3C4E7BAF7BD3BC14ULL) + aPhaseDOrbiterAssignSaltD[((aIndex + 8U)) & S_SALT1];
            aOrbiterC = ((aWandererB + RotL64(aPrevious, 11U)) + 0x5CAF0DDEF4B3BB29ULL) + aPhaseDOrbiterAssignSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterI = (aWandererJ + RotL64(aScatter, 47U)) + 0xCE1B4FB8213687D4ULL;
            aOrbiterB = (aWandererK + RotL64(aIngress, 5U)) + 0x9305AC8E32D18F50ULL;
            aOrbiterD = ((aWandererE + RotL64(aScatter, 41U)) + RotL64(aCarry, 23U)) + 0x2537349EE80DA387ULL;
            aOrbiterK = ((aWandererC + RotL64(aCross, 26U)) + RotL64(aCarry, 37U)) + 0x8735B6841279B107ULL;
            aOrbiterH = ((aWandererF + RotL64(aPrevious, 19U)) + RotL64(aCarry, 3U)) + 0xDC60F5967D2C33B9ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0xDD88894243C6BB8DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x2C98218743A52DE4ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xD6FA381175B1EA47ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x7F230BD8D2405F16ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x9E02C43820628587ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xB4D8D8426EDD97E7ULL), 41U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0x241F22878CCA59B5ULL) + aPhaseDOrbiterUpdateSaltF[((aIndex + 17U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x22DBDE9971581CDEULL;
            aOrbiterC = RotL64((aOrbiterC * 0xFA974A1D4854207DULL), 19U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterH) + 0xDD1E81353426DA41ULL) + aPhaseDOrbiterUpdateSaltC[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0xE312BE0C1C9764C4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x0349892AEFB3CDEDULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x1A0D07BA09697332ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x3DBB372A6B115B07ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x5ABFBD12875B9409ULL), 3U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0x2A03B9F322E3D33DULL) + aPhaseDOrbiterUpdateSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x0D1B41BE0CFD0BD2ULL;
