            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0xC8A109E0A65D3A7CULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterI) ^ 0x88211272B33D9468ULL) ^ aPhaseDOrbiterUpdateSaltB[(((31U - aIndex) + 28U)) & S_SALT1];
