            aWandererC = aWandererC ^ (((RotL64(aScatter, 27U) + aOrbiterD) + RotL64(aOrbiterK, 3U)) + aPhaseDWandererUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1]);
