            aOrbiterC = ((aWandererA + RotL64(aScatter, 29U)) + RotL64(aCarry, 29U)) + 0x592A8AC7D3CC1AC5ULL;
            aOrbiterB = (aWandererE + RotL64(aCross, 6U)) + 0xB4E70CE76154F769ULL;
            aOrbiterI = (((aWandererJ + RotL64(aPrevious, 19U)) + RotL64(aCarry, 13U)) + 0x76139ABAE98350EAULL) + aPhaseAOrbiterAssignSaltA[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterK = (aWandererB + RotL64(aIngress, 51U)) + 0x5F62DF1459597E27ULL;
            aOrbiterA = (aWandererG + RotL64(aScatter, 35U)) + 0xAFE556A80D6F6B0FULL;
            aOrbiterH = (((aWandererK + RotL64(aIngress, 43U)) + RotL64(aCarry, 53U)) + 0xACF1A7EFE1D5529FULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 7U)) & S_SALT1];
            aOrbiterE = (aWandererC + RotL64(aCross, 57U)) + 0x1ADAE2BCD0D56EEDULL;
