            aOrbiterK = RotL64((aOrbiterK * 0xB875AA8E1DAC9C5BULL), 11U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x4084B07E9F792906ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x4F868C9C6F8F8774ULL;
