            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x0C3AC6E7235809A3ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0xB3FAF9E0DA9C0421ULL) ^ aPhaseAOrbiterUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
