            aWandererK = aWandererK + ((((RotL64(aPrevious, 29U) + RotL64(aOrbiterB, 5U)) + aOrbiterA) + RotL64(aCarry, 41U)) + aPhaseAWandererUpdateSaltC[((aIndex + 15U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 3U) + aOrbiterC) + RotL64(aOrbiterB, 11U));
